/*
Mockingboard music demo for the Apple ][.

A Mockingboard C plugs into a slot (slot 4 here, so it appears at $C400)
and carries two AY-3-8913 PSGs, each hidden behind a 6522 VIA.  The AY is
not connected to the Apple bus -- you have to bit-bang it through the VIA:
put the AY register number or value on port A, then pulse BC1/BDIR on port
B to latch an address or write data.  $C400 is the first VIA/AY and $C480
the second.

Port B bit 0 = BC1, bit 1 = BDIR, bit 2 = /RESET (must stay high).  BC1/BDIR
is 11 to latch an address and 01 to write data; both are bracketed by 00
(inactive), because the AY only reacts while it is idle.

The same 6522 also runs its Timer 1 continuously at 60 Hz, setting the T1
flag in the interrupt flag register on each rollover.  The main loop polls
that flag to step the music, so the tempo is derived from the CPU clock
(~1.0227 MHz) instead of a delay loop.  The VIA IRQ line does reach the
Apple bus, but Timer 1 interrupts are left disabled, so the ROM's IRQ
handler (which would reset the machine) is never entered.
*/

#include <conio.h>

#define MB1 0xC400             /* slot 4, first  VIA/AY  */
#define MB2 0xC480             /* slot 4, second VIA/AY  */

#define AY_OFF   0x04          /* inactive, /RESET high */
#define AY_WRITE 0x06
#define AY_LATCH 0x07

/* 6522 VIA registers, as offsets from a base address */
#define VIA_T1CL 0x04          /* timer 1 counter/latch, low */
#define VIA_T1CH 0x05          /* timer 1 counter/latch, high (starts timer) */
#define VIA_ACR  0x0b          /* auxiliary control register */
#define VIA_IFR  0x0d          /* interrupt flag register */

/* The VIA is clocked by the ~1.0227 MHz CPU clock: 1022727 / 60 = 17045 */
#define TIMER_60HZ 17045

/* pulse the VIA ports to move one byte to/from the AY */
void ay_set(unsigned base, unsigned char reg, unsigned char val)
{
    volatile unsigned char *orb = (volatile unsigned char *)base;
    volatile unsigned char *ora = orb + 1;
    *orb = AY_OFF;
    *ora = reg;
    *orb = AY_LATCH;           /* latch register number */
    *orb = AY_OFF;
    *ora = val;
    *orb = AY_WRITE;           /* write data */
    *orb = AY_OFF;
}

void ay_init(unsigned base)
{
    unsigned char r;
    for (r = 0; r < 14; r++)
        ay_set(base, r, 0);
    ay_set(base, 7, 0x3f);         /* start with every generator off */
}

/* start 6522 Timer 1 free-running at 60 Hz */
void timer_init(unsigned base)
{
    volatile unsigned char *via = (volatile unsigned char *)base;
    via[VIA_ACR]  = 0x40;              /* T1 continuous, PB7 stays an I/O */
    via[VIA_T1CL] = TIMER_60HZ & 0xff;
    via[VIA_T1CH] = TIMER_60HZ >> 8;   /* load latch and start counting */
}

/* returns 1 once per 60 Hz rollover, clearing the T1 flag */
unsigned char timer_tick(unsigned base)
{
    volatile unsigned char *via = (volatile unsigned char *)base;
    if (via[VIA_IFR] & 0x40) {         /* timer 1 rolled over */
        via[VIA_IFR] = 0x40;           /* clear the T1 flag */
        return 1;
    }
    return 0;
}

void ay_set_tone(unsigned base, unsigned char ch, unsigned int period)
{
    ay_set(base, ch * 2, period & 0xff);
    ay_set(base, ch * 2 + 1, period >> 8);
}

void ay_set_vol(unsigned base, unsigned char ch, unsigned char vol)
{
    ay_set(base, 8 + ch, vol & 0x0f);
}


