static const byte* music_ptr = 0;
static const byte* music_rts = 0;
static byte music_runlen = 0;

// decode next music byte, handling compression
byte next_music_byte(void) {
  byte ch = *music_ptr++;
  if (music_runlen) {
    // we are in a backreference, count down
    if (--music_runlen == 0) {
      music_ptr = music_rts;
      music_rts = 0;
    }
  } else if (ch == 0xfe) {
    // back-reference: 0xfe <offset> <length>
    byte offset = *music_ptr++;
    music_runlen = *music_ptr++;
    music_rts = music_ptr;
    music_ptr -= offset + 3;
    return next_music_byte();
  }
  return ch;
}

void play_music() {
  byte ch;
  byte enable = 0;
  byte freech = 0;
  byte chmask = 1;
  for (ch=0; ch<3; ch++) {
    if (voice[ch].volume) {
      ay_set_vol(MB1, ch, voice[ch].volume--);
      enable |= chmask;
    } else {
      freech = ch;
    }
    chmask <<= 1;
  }
  //ay_set(MB1, 7, ~enable);
  if (music_ptr) {
    ch = freech;
    while (cur_duration == 0) {
      byte note = next_music_byte();
      if ((note & 0x80) == 0) {
        int period = note_table[note & 63];
        ay_set_tone(MB1, ch, period);
        voice[ch].volume = 15;
        ch = ch ? ch-1 : 2;
      } else {
        if (note == 0xff)
          music_ptr = NULL;
        cur_duration = note & 63;
      }
    }
    cur_duration--;
  }
}

void start_music(const byte* music) {
  music_ptr = music;
  music_rts = 0;
  music_runlen = 0;
  cur_duration = 0;
}

#ifdef __MAIN__

void main(void)
{
    unsigned char s;

    clrscr();
    gotoxy(8, 4);
    cputs("MOCKINGBOARD DEMO");
    gotoxy(8, 8);
    cputs("AY-3-8913 x2 IN SLOT 4");
    gotoxy(8, 12);
    cputs("ESC TO STOP");

    ay_init(MB1);
    ay_init(MB2);
    ay_set(MB1, 7, 0x38);          /* tone A/B/C on, noise off */
    //ay_set(MB2, 7, 0x37);          /* noise A only */
    timer_init(MB1);               /* 60 Hz clock to drive the music */

    for (;;) {
        if (!music_ptr) start_music(music1);
        play_music();
        while (!timer_tick(MB1))
            ;                      /* wait for the next 60 Hz tick */
        if (kbhit() && cgetc() == 27)
            break;
    }

    ay_set(MB1, 7, 0);
}

#endif
